const input = $input.all();
return input.map((item) => {
  const title = item.json.title || item.json.name || 'Source sans titre';
  const link = item.json.link || item.json.url || '';
  const date = item.json.isoDate || item.json.pubDate || new Date().toISOString();
  const text = [title, item.json.contentSnippet, item.json.content, item.json.summary].filter(Boolean).join('\n').slice(0, 1200);
  const slug = title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 84) || 'veille-item';
  return {
    json: {
      title,
      link,
      date,
      slug,
      source: item.json.creator || item.json.author || item.json['dc:creator'] || '',
      tags: ['n8n-veille', 'a-verifier'],
      status: 'a verifier',
      summary: text
    }
  };
});

return $input.all().map((item) => {
  const j = item.json;
  const day = new Date().toISOString().slice(0, 10);
  const md = `# ${j.title}

## Type

Veille n8n / source externe.

## Tags

${j.tags.join(', ')}

## Sources

- Source : ${j.link || 'A_VERIFIER'}

Lecture KM : ${day}

## Resume court

${j.summary || 'A completer.'}

## Classification

\`${j.status}\`

Raison : source importee par template n8n, validation humaine requise.

## Usage KM

- Surveiller comme signal faible ou ressource a auditer.
- Verifier la source primaire avant decision produit.

## Risque d'abus possible

Claims non verifies, source secondaire, contenu externe a auditer.

## Historique

### v0.1 - ${day}

- Brouillon genere par workflow n8n.
`;
  return { json: { ...j, markdown: md, path: `/opt/km-dashboard/watch/${j.slug}.md` } };
});
